import {renderComponentCards} from './cards.mjs';
import {categories} from '../admin/data.mjs';
import {catalogue,productById} from './catalogue.mjs';
import {addComponent} from '../commerce.mjs';
renderComponentCards();
const filters=['shaft','brand','type'].map(key=>document.querySelector('#filter-'+key));
function filterPots(){let count=0;for(const product of catalogue.filter(p=>p.category==='potentiometers')){if(!document.getElementById(product.id))continue;const visible=(filters[0].value==='all'||product.specs.Shaft===filters[0].value)&&(filters[1].value==='all'||product.manufacturer===filters[1].value)&&(filters[2].value==='all'||product.specs.Type===filters[2].value);document.getElementById(product.id).hidden=!visible;if(visible)count++;}document.querySelector('#pot-count').textContent=`${count} option${count===1?'':'s'}`;}
if(filters[1]){const selected=filters[1].value;filters[1].replaceChildren();for(const brand of ['all',...new Set(catalogue.filter(p=>p.category==='potentiometers').map(p=>p.manufacturer).filter(Boolean))]){const option=document.createElement('option');option.value=brand;option.textContent=brand==='all'?'All manufacturers':brand;filters[1].append(option);}filters[1].value='all';}
if(filters.every(Boolean))filterPots();
filters.filter(Boolean).forEach(field=>field.addEventListener('change',filterPots));
document.querySelectorAll('[data-add]').forEach(button=>{button.disabled=productById(button.dataset.add).stock===0||!Number.isFinite(productById(button.dataset.add).price);button.addEventListener('click',()=>{const feedback=button.closest('article').querySelector('.product-feedback');try{addComponent(button.dataset.add);feedback.textContent='Added to your basket.';const a=document.createElement('a');a.href='/basket/';a.textContent=' View basket ↗';feedback.append(a);}catch(error){feedback.textContent=error.message;}});});
function revealLinkedProduct(){const product=productById(location.hash.slice(1));if(product?.category==='potentiometers'&&filters.every(Boolean)){filters.forEach(f=>f.value='all');filterPots();document.getElementById(product.id)?.scrollIntoView();}}
window.addEventListener('hashchange',revealLinkedProduct);revealLinkedProduct();
// One restrained category filter on the all-components page; product data and basket logic are unchanged.
const categoryLinks=[...document.querySelectorAll('[data-category-filter]')],sections=[...document.querySelectorAll('.component-section')];
function showCategory(category,writeURL=false){if(!['all',...Object.keys(categories)].includes(category))category='all';for(const section of sections)section.hidden=category!=='all'&&section.id!==category;for(const a of categoryLinks){if(a.dataset.categoryFilter===category)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');}if(writeURL){const url=new URL(location.href);if(category==='all')url.searchParams.delete('category');else url.searchParams.set('category',category);url.hash='';history.replaceState(null,'',url);}const status=document.querySelector('#component-status');if(status)status.textContent=category==='all'?'Showing all components.':'Showing '+category.replace('-',' ')+'.';}
function categoryFromURL(){const product=productById(decodeURIComponent(location.hash.slice(1)));return product?.category||(Object.keys(categories).includes(location.hash.slice(1))?location.hash.slice(1):new URLSearchParams(location.search).get('category')||'all');}
if(categoryLinks.length){categoryLinks.forEach(a=>a.addEventListener('click',e=>{e.preventDefault();showCategory(a.dataset.categoryFilter,true);}));showCategory(categoryFromURL());window.addEventListener('hashchange',()=>showCategory(categoryFromURL()));window.addEventListener('popstate',()=>showCategory(categoryFromURL()));}
